fn find_smallest(s: &Vec<nat>) -> Option<nat> {
    // If the slice is empty, there is no smallest element.
    if s.is_empty() {
        return None;
    }
    // Initialize the smallest value to the first element.
    let mut smallest = s[0];
    // Iterate over the remaining elements and update `smallest` if we find a smaller one.
    for &value in &s[1..] {
        if value < smallest {
            smallest = value;
        }
    }
    Some(smallest)
}

